mapper.select:
SELECT BATCH_ID, FILE_TYPE, FILE_NAME, FILE_PATH, BYTE_COUNT, RECORD_COUNT, AMOUNT_TOTAL, SHA256, STATUS, REMOTE_PATH
FROM RECON_BATCH_FILE
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR} AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}

mapper.update:
UPDATE RECON_BATCH_FILE
SET STATUS = #{status,jdbcType=VARCHAR}, REMOTE_PATH = #{remotePath,jdbcType=VARCHAR}, UPDATED_AT = SYSTIMESTAMP
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR} AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}
